          reviewBox.innerHTML=`<h3>${t('Review business setup','مراجعة إعداد النشاط')}</h3><p>${esc(review.user.name)} · ${esc(review.user.email)} → ${esc(review.businessName)}</p><p>${esc(review.category.title[ar()?'ar':'en'])} · ${esc(review.contract.commercial.title)} · ${esc(review.contract.commercial.price)} ${'QAR'} · ${esc(review.contract.commercial.plan_duration_in_days)} ${t('days from confirmation','يومًا من التأكيد')}</p><p>${Object.entries(review.proposedLimits).map(([role,count])=>`${esc(t(...roleNamesShort[role]))}: ${count} / ${review.contract.ceiling[role]}`).join(' · ')}</p><p>${t('Features enabled','الميزات المفعلة')}: ${review.contract.capabilities.map(esc).join(', ')}</p>${review.blockers.length?`<div role="alert" class="sx-plan-message">${review.blockers.map(esc).join(' · ')}</div>`:`<p role="status">${t('Preview only. No account or plan has changed.','معاينة فقط. لم يتغير الحساب أو الخطة.')}</p><button type="button" data-provision-confirm>${t('Create business and assign plan','إنشاء النشاط وتعيين الخطة')}</button>`}`;
